# bash completion for capm. Generated by "capm completion bash"; do not edit.
#
#   eval "$(capm completion bash)"                      # this shell only (also on bash 3.2, where source <(...) does not work)
#   capm completion bash > ~/.local/share/bash-completion/completions/capm
#
# Works with bash 3.2 and later; it needs only "complete -F", not the
# bash-completion package. Bundle references come from "capm __complete
# bundles", which asks the registry for at most one second and never fails.

_capm_words() {
  COMPREPLY=( $(compgen -W "$1" -- "$cur") )
}

_capm_bundles() {
  COMPREPLY=( $("${COMP_WORDS[0]}" __complete bundles "$cur" 2>/dev/null) )
}

# _capm_files -d|-f: bash 4+ completes (and quotes) names itself; on bash 3.2,
# which has no compopt, COMPREPLY stays empty and the "-o default" given to
# complete below makes readline complete file names.
_capm_files() {
  if type compopt >/dev/null 2>&1; then
    local IFS=$'\n'
    compopt -o filenames 2>/dev/null
    COMPREPLY=( $(compgen "$1" -- "$cur") )
  fi
}

_capm_ref_or_dir() {
  case "$cur" in
    ./*|../*|/*|"~"*|.|..) _capm_files -d; return 0 ;;
  esac
  _capm_bundles
  if [ "${#COMPREPLY[@]}" -eq 0 ]; then _capm_files -d; fi
}

_capm() {
  local cur prev
  COMPREPLY=()
  cur="${COMP_WORDS[COMP_CWORD]}"
  prev=""
  if [ "$COMP_CWORD" -ge 1 ]; then prev="${COMP_WORDS[COMP_CWORD-1]}"; fi
  # readline splits --flag=value into three words: --flag, =, value.
  if [ "$cur" = "=" ]; then cur=""; fi
  if [ "$prev" = "=" ] && [ "$COMP_CWORD" -ge 2 ]; then prev="${COMP_WORDS[COMP_CWORD-2]}"; fi

  if [ "$COMP_CWORD" -le 1 ]; then _capm_words "login whoami orgs logout tokens usage init lint push pull inspect run search list report known self-update outdated completion version"; return 0; fi
  case "${COMP_WORDS[1]}" in
    login)
      case "$prev" in
        --audience|-audience) return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--orgs --oidc --audience"; return 0 ;;
      esac
      # no positional argument is completed
      return 0
      ;;
    whoami)
      # no positional argument is completed
      return 0
      ;;
    orgs)
      # no positional argument is completed
      return 0
      ;;
    logout)
      # no positional argument is completed
      return 0
      ;;
    tokens)
      if [ "$COMP_CWORD" -eq 2 ]; then _capm_words "revoke"; return 0; fi
      case "${COMP_WORDS[2]}" in
        revoke)
          # no positional argument is completed
          return 0
          ;;
      esac
      return 0
      ;;
    usage)
      case "$prev" in
        --owner|-owner) return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--owner"; return 0 ;;
      esac
      # no positional argument is completed
      return 0
      ;;
    init)
      case "$prev" in
        --name|-name) return 0 ;;
        --description|-description) return 0 ;;
        --author|-author) return 0 ;;
        --base|-base) _capm_words "claude-code opencode"; return 0 ;;
        --base-version|-base-version) return 0 ;;
        --egress|-egress) return 0 ;;
        --mount|-mount) _capm_files -f; return 0 ;;
        --secret|-secret) return 0 ;;
        --repository|-repository) return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--yes --name --description --author --base --base-version --egress --mount --secret --repository"; return 0 ;;
      esac
      _capm_files -d
      return 0
      ;;
    lint)
      case "$prev" in
        --owner|-owner) return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--strict --offline --owner"; return 0 ;;
      esac
      _capm_files -d
      return 0
      ;;
    push)
      case "$prev" in
        --owner|-owner) return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--allow-secret-files --owner"; return 0 ;;
      esac
      _capm_files -d
      return 0
      ;;
    pull)
      case "$cur" in
        -*) _capm_words "--accept-new-owner"; return 0 ;;
      esac
      _capm_bundles
      return 0
      ;;
    inspect)
      case "$cur" in
        -*) _capm_words "--diff"; return 0 ;;
      esac
      _capm_ref_or_dir
      return 0
      ;;
    run)
      case "$prev" in
        --workdir|-workdir) _capm_files -d; return 0 ;;
        --model-url|-model-url) return 0 ;;
        --model-key|-model-key) return 0 ;;
        --model|-model) return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--yes --allow-unenforced-egress --allow-global-anthropic-secret --accept-new-owner --accept-permission-changes --accept-changed-digest --workdir --model-url --model-key --model"; return 0 ;;
      esac
      _capm_ref_or_dir
      return 0
      ;;
    search)
      case "$prev" in
        --sort|-sort) _capm_words "name recent downloads"; return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--sort"; return 0 ;;
      esac
      # no positional argument is completed
      return 0
      ;;
    list)
      case "$prev" in
        --sort|-sort) _capm_words "name recent downloads"; return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--sort"; return 0 ;;
      esac
      # no positional argument is completed
      return 0
      ;;
    report)
      case "$prev" in
        --reason|-reason) _capm_words "malware secrets-exposed impersonation other"; return 0 ;;
        --details|-details) return 0 ;;
      esac
      case "$cur" in
        -*) _capm_words "--reason --details"; return 0 ;;
      esac
      _capm_bundles
      return 0
      ;;
    known)
      if [ "$COMP_CWORD" -eq 2 ]; then _capm_words "forget"; return 0; fi
      case "${COMP_WORDS[2]}" in
        forget)
          _capm_bundles
          return 0
          ;;
      esac
      return 0
      ;;
    self-update)
      case "$cur" in
        -*) _capm_words "--check"; return 0 ;;
      esac
      # no positional argument is completed
      return 0
      ;;
    outdated)
      # no positional argument is completed
      return 0
      ;;
    completion)
      if [ "$COMP_CWORD" -eq 2 ]; then _capm_words "bash zsh fish"; fi
      return 0
      ;;
    version)
      # no positional argument is completed
      return 0
      ;;
    admin)
      if [ "$COMP_CWORD" -eq 2 ]; then _capm_words "remove restore ban unban revoke-tokens quota log reports report resolve"; return 0; fi
      case "${COMP_WORDS[2]}" in
        remove)
          case "$prev" in
            --reason|-reason) return 0 ;;
          esac
          case "$cur" in
            -*) _capm_words "--reason"; return 0 ;;
          esac
          _capm_bundles
          return 0
          ;;
        restore)
          _capm_bundles
          return 0
          ;;
        ban)
          case "$prev" in
            --reason|-reason) return 0 ;;
          esac
          case "$cur" in
            -*) _capm_words "--reason"; return 0 ;;
          esac
          # no positional argument is completed
          return 0
          ;;
        unban)
          # no positional argument is completed
          return 0
          ;;
        revoke-tokens)
          # no positional argument is completed
          return 0
          ;;
        quota)
          case "$prev" in
            --bytes|-bytes) return 0 ;;
            --bundles|-bundles) return 0 ;;
          esac
          case "$cur" in
            -*) _capm_words "--bytes --bundles --reset"; return 0 ;;
          esac
          # no positional argument is completed
          return 0
          ;;
        log)
          # no positional argument is completed
          return 0
          ;;
        reports)
          case "$cur" in
            -*) _capm_words "--all --resolved"; return 0 ;;
          esac
          # no positional argument is completed
          return 0
          ;;
        report)
          # no positional argument is completed
          return 0
          ;;
        resolve)
          case "$prev" in
            --note|-note) return 0 ;;
          esac
          case "$cur" in
            -*) _capm_words "--note"; return 0 ;;
          esac
          # no positional argument is completed
          return 0
          ;;
      esac
      return 0
      ;;
  esac
  return 0
}

if type compopt >/dev/null 2>&1; then
  complete -F _capm capm
else
  complete -o default -F _capm capm
fi
